import json
import itertools

def t_to_min(t):
    h, m = map(int, t.split(":"))
    return h * 60 + m

def min_to_t(m):
    h = m // 60
    mm = m % 60
    return f"{h}:{mm:02d}"

def compare_scores(a, b):
    # Higher count better, then higher meeting minutes, then lower wait+travel
    key_a = (a["count"], a["meet_minutes"], -a["wait_travel"])
    key_b = (b["count"], b["meet_minutes"], -b["wait_travel"])
    return (key_a > key_b) - (key_a < key_b)

def plan_schedule(start_location, start_time, participants, travel_times):
    # Try all permutations and use DFS with branching (meet/skip + variable meeting end)
    best_overall = {"count": -1, "meet_minutes": -1, "wait_travel": float("inf"), "itinerary": []}

    # Precompute an index for participants
    people = participants[:]
    all_orders = list(itertools.permutations(people, len(people)))

    def search(order, idx, cur_loc, cur_time):
        if idx == len(order):
            return {"count": 0, "meet_minutes": 0, "wait_travel": 0, "itinerary": []}

        person = order[idx]
        p_loc = person["location"]
        p_start = person["start"]
        p_end = person["end"]
        p_min = person["min_duration"]

        # Option 1: Skip this person
        best = search(order, idx + 1, cur_loc, cur_time)

        # Option 2: Try to meet this person (if travel path exists)
        travel_key = (cur_loc, p_loc)
        if travel_key in travel_times:
            travel = travel_times[travel_key]
            arrival = cur_time + travel
            wait = max(0, p_start - arrival)
            meet_start = max(arrival, p_start)

            if meet_start + p_min <= p_end:
                earliest_end = meet_start + p_min
                latest_end = p_end
                # Try longer meetings first to favor more meeting time
                for end_t in range(latest_end, earliest_end - 1, -1):
                    rest = search(order, idx + 1, p_loc, end_t)
                    if rest is None:
                        continue
                    candidate = {
                        "count": 1 + rest["count"],
                        "meet_minutes": (end_t - meet_start) + rest["meet_minutes"],
                        "wait_travel": (wait + travel) + rest["wait_travel"],
                        "itinerary": [{
                            "action": "meet",
                            "location": p_loc,
                            "person": person["name"],
                            "start_time_min": meet_start,
                            "end_time_min": end_t
                        }] + rest["itinerary"]
                    }
                    if compare_scores(candidate, best) > 0:
                        best = candidate

        return best

    for order in all_orders:
        candidate = search(order, 0, start_location, start_time)
        if compare_scores(candidate, best_overall) > 0:
            best_overall = candidate

    # Convert itinerary times to strings and ensure correct fields
    output_itinerary = []
    for item in best_overall["itinerary"]:
        output_itinerary.append({
            "action": "meet",
            "location": item["location"],
            "person": item["person"],
            "start_time": min_to_t(item["start_time_min"]),
            "end_time": min_to_t(item["end_time_min"])
        })

    return {"itinerary": output_itinerary}

def main():
    # Input variables based on the problem statement
    start_location = "North Beach"
    start_time = t_to_min("9:00")

    # Travel times (in minutes), directional
    travel_times = {
        ("North Beach", "Union Square"): 7,
        ("North Beach", "Russian Hill"): 4,
        ("Union Square", "North Beach"): 10,
        ("Union Square", "Russian Hill"): 13,
        ("Russian Hill", "North Beach"): 5,
        ("Russian Hill", "Union Square"): 11
    }

    # Participants and constraints
    participants = [
        {
            "name": "Emily",
            "location": "Union Square",
            "start": t_to_min("16:00"),
            "end": t_to_min("17:15"),
            "min_duration": 45
        },
        {
            "name": "Margaret",
            "location": "Russian Hill",
            "start": t_to_min("19:00"),
            "end": t_to_min("21:00"),
            "min_duration": 120
        }
    ]

    plan = plan_schedule(start_location, start_time, participants, travel_times)
    print(json.dumps(plan, ensure_ascii=False))

if __name__ == "__main__":
    main()
